using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class Tools
{
    [McpServerTool, Description("Echo the input message back with a timestamp.")]
    public static string Echo(
        [Description("The message to echo")] string message)
    {
        return $"[{DateTime.UtcNow:O}] {message}";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class Resources
{
    [McpServerResource(UriTemplate = "config://app", Name = "App Config",
        MimeType = "application/json"),
     Description("Returns application configuration data.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "HttpMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://features/{name}", Name = "Feature Flag",
        MimeType = "application/json"),
     Description("Returns whether a specific feature flag is enabled.")]
    public static string GetFeatureFlag(
        [Description("The feature flag name to look up")] string name)
    {
        var flags = new Dictionary<string, bool>
        {
            ["dark-mode"] = true,
            ["beta-api"] = false,
            ["caching"] = true
        };

        var result = new { Feature = name, Enabled = flags.GetValueOrDefault(name, false) };
        return JsonSerializer.Serialize(result);
    }
}

